mapper.select:
select summary.id AS whId, summary.product_id, summary.user_name, summary.quantity AS warehouseQuantity, CONVERT(IFNULL(part.mete, 0) / part.quantity, DECIMAL(18,4)) * summary.quantity warehouseMete, project.id AS 'project.id', project.name AS 'project.name', project.short_name AS 'project.shortName', monomer.id AS 'monomer.id', monomer.name AS 'monomer.name', area.id AS 'monomer.id', area.name AS 'area.name', part.* from mes_building_warehouse_summary summary LEFT JOIN tech_standard_part part on summary.product_id = part.id and part.bool_delete_enum = 0 and part.use_property = 1 LEFT JOIN contract_project project on project.id = part.project_id LEFT JOIN plan_monomer monomer on monomer.id = part.monomer_id LEFT JOIN plan_area area on area.id = part.area_id where summary.product_type = 8 and summary.type = 1 and summary.project_id = #{projectId} and summary.warehouse_type = 0 and summary.bool_delete_enum = 0
and summary.monomer_id = #{monomerId}
and summary.area_id = #{areaId}
and part.name like concat('%',#{name},'%')
and part.specification like concat('%',#{specification},'%')
